"""Create a fictional policy and an independent clause inventory for HMH tests."""
from pathlib import Path
import json
from html import escape
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'output/pdf'
OUT.mkdir(parents=True, exist_ok=True)
# All terms below are invented for software testing, not a real insurance contract.
SECTIONS = [
('Policy schedule', [
('01','Your selected cover and payment option',
'The fictional insurer is Nivara Demo Assurance. The product is Nivara ClearCare, version DEMO-1.0. This individual policy covers one fictional adult member, DEMO-MEMBER-A, age 35. Cover starts on 1 December 2026 and ends on 30 November 2027. The annual benefit limit is INR 500,000. The selected premium is INR 12,000, payable once each policy year. The monthly payment option is NOT selected. No optional rider is selected.',
['One adult member is covered from 1 December 2026 through 30 November 2027.','The annual benefit limit is INR 500,000.','The selected premium is INR 12,000 once per policy year, not INR 1,000 each month.','No optional rider is included.']),
]),
('Definitions and eligibility', [
('02','Who can be covered', 'New members must be aged 18 through 60 on the cover start date. This policy covers only the person named in the schedule. A spouse, parent, child or other family member is not automatically covered. A separate policy is required for any additional person.', ['Entry age is 18 through 60.','Only the scheduled member is covered; family members are not automatically included.']),
('03','What a policy year means', 'A policy year is the 12-month period shown in the schedule. Every claim payment, including an ambulance or dental payment, uses the same annual benefit limit. Unused benefit does not carry forward. The limit is not automatically restored after a claim.', ['All covered benefits share one annual limit.','Unused benefit does not carry forward and there is no automatic restoration.']),
('04','Eligible treatment and hospital stay', 'Eligible treatment means medically necessary treatment of an illness or accidental injury, prescribed by a treating clinician, that is not excluded or subject to an uncompleted waiting period. A hospital admission normally must last at least 24 continuous hours. The day-care exception in clause 09 applies even when an admission is shorter.', ['Treatment must satisfy coverage, necessity and waiting-period conditions.','A 24-hour admission is normally required, with the day-care exception.']),
('05','Where cover applies', 'Treatment is covered only when received within India. Treatment outside India is excluded, even during an emergency. A hospital being outside the network does not by itself remove cover; the reimbursement procedure in clause 27 applies.', ['Treatment must occur in India, including emergencies.','A non-network hospital can qualify for reimbursement.']),
('06','Annual deductible and co-payment', 'The member pays the first INR 10,000 of otherwise eligible expenses in each policy year as an aggregate deductible. After that deductible is used, the member pays 10 percent of remaining eligible expenses and the insurer pays 90 percent, subject to the remaining annual limit. Benefit sublimits are applied before this calculation. Excluded expenses never use up the deductible.', ['INR 10,000 is one aggregate deductible per policy year, not per admission.','After the deductible, the member pays 10 percent and the insurer pays 90 percent of eligible expenses.','Benefit sublimits apply first; excluded expenses do not exhaust the deductible.']),
]),
('Covered benefits and limits', [
('07','Inpatient hospital treatment', 'Eligible inpatient room charges, nursing, operation-theatre charges, prescribed medicines used during admission and clinician fees are covered, subject to this policy. The insurer does not promise to pay every item on a hospital bill. Room limits, exclusions, the deductible, co-payment and annual limit still apply.', ['Specified eligible inpatient expenses are covered.','Coverage does not mean the whole bill is paid; all limits and cost sharing still apply.']),
('08','Room charge limit', 'The eligible room charge is capped at INR 3,000 for each covered day. The member pays any room charge above that daily cap. Choosing a more expensive room does not reduce other otherwise eligible treatment charges proportionately; only the room excess is excluded under this clause.', ['Room charges are capped at INR 3,000 per covered day.','The member pays the room excess.','There is no proportionate reduction of other eligible treatment charges for choosing a higher-priced room.']),
('09','Day-care exception', 'Cataract surgery and dialysis are covered day-care procedures even if the hospital stay is shorter than 24 hours, when all other conditions are met. An ordinary outpatient consultation does not become covered merely because it occurs in a hospital. These day-care benefits share the annual limit and remain subject to applicable waiting periods.', ['Cataract surgery and dialysis can qualify without a 24-hour admission.','Ordinary outpatient consultations are not included by this exception.','Applicable waiting periods and the annual limit still apply.']),
('10','Ambulance sublimit', 'A road ambulance to a hospital is eligible up to INR 2,000 per covered admission, within the annual limit. There is no separate extra annual ambulance fund. Air ambulance and routine transport home after discharge are not covered. The deductible and co-payment apply to the eligible ambulance amount.', ['Road ambulance is limited to INR 2,000 per covered admission within the annual limit.','Air ambulance and routine transport home are excluded.','Deductible and co-payment apply.']),
('11','Accidental dental injury exception', 'Dental treatment is normally excluded. An exception covers repair of teeth directly injured in an accident occurring during active cover, up to INR 5,000 per policy year. Routine cleaning, tooth decay, dentures unrelated to that accident and cosmetic whitening remain excluded. The exception shares the annual limit and normal cost sharing.', ['Accidental dental repair has a limit of INR 5,000 per policy year.','Routine and cosmetic dental work remain excluded.','This benefit shares the annual limit and cost sharing.']),
]),
('Exclusions and uncommon situations', [
('12','Outpatient treatment and medicines', 'Routine outpatient consultations, health check-ups, vaccinations and medicines taken outside an eligible hospital or covered day-care treatment are excluded. Prescription by a clinician alone does not make an otherwise excluded outpatient expense payable.', ['Routine outpatient services, check-ups, vaccinations and unrelated take-home medicines are excluded.','A prescription alone does not override the exclusion.']),
('13','Cosmetic and reconstructive treatment', 'Treatment performed solely to change appearance is excluded. Reconstructive surgery required to repair an accidental injury during active cover may be eligible when prescribed by the treating clinician. The accident exception does not cover an unrelated cosmetic improvement performed in the same admission.', ['Purely cosmetic treatment is excluded.','Accident-related reconstruction may qualify.','An unrelated cosmetic addition remains excluded even in the same admission.']),
('14','Maternity and fertility treatment', 'Pregnancy-related care, childbirth, fertility treatment and newborn care are excluded under this base policy. The schedule contains no maternity rider. An unrelated covered illness in the insured adult is assessed under the ordinary terms and is not automatically excluded simply because the adult is pregnant.', ['The base policy has no maternity, fertility or newborn benefit.','There is no maternity rider in this schedule.','An unrelated covered illness is assessed under the ordinary terms.']),
('15','High-altitude sports edge case', 'Injury while participating in recreational climbing above 4,000 metres is excluded. Ordinary travel or residence above that altitude is not excluded by this clause alone. A fall while walking to a hotel is not automatically treated as recreational climbing; the activity actually undertaken must be established.', ['Recreational climbing injury above 4,000 metres is excluded.','Ordinary travel or residence at that altitude is not excluded by this clause alone.','The actual activity matters when applying this exclusion.']),
('16','Documents and identity misuse', 'A knowingly fabricated bill or a claim made for someone other than the scheduled member is not payable. An accidental spelling error is not by itself proof of fabrication. The member must be given an opportunity to supply the correct details before a decision based solely on that mismatch.', ['Fabricated bills and claims for another person are not payable.','An accidental spelling mismatch alone does not establish fabrication.','The member can correct a spelling mismatch before a decision based only on that mismatch.']),
]),
('Waiting periods', [
('17','Initial illness waiting period', 'Illness claims arising during the first 30 days from the original cover start date are excluded. Accidental injuries occurring after cover starts do not have this initial 30-day wait. On uninterrupted renewal, the initial waiting period does not restart.', ['There is a 30-day initial wait for illness.','Accidents after the start of cover are exempt from this initial wait.','The initial wait does not restart on uninterrupted renewal.']),
('18','Specified treatment waiting period', 'Planned joint replacement has a 24-month waiting period of continuous cover from the original start date. Joint repair directly required by a new accident during active cover is not subject to this specified-treatment wait. A different exclusion or an applicable longer waiting period can still prevent payment.', ['Planned joint replacement has a 24-month continuous-cover wait.','New accident-related joint repair is exempt from this specified wait.','Other exclusions or a longer applicable wait may still apply.']),
('19','Pre-existing condition waiting period', 'A condition diagnosed before the original cover start date, or for which treatment was advised during the preceding 24 months, is a pre-existing condition for this fictional policy. Eligible claims related to it have a 36-month continuous-cover wait. Completion of the initial 30-day wait does not remove this separate restriction.', ['The definition includes diagnosis before inception or advised treatment in the preceding 24 months.','Related claims have a 36-month continuous-cover wait.','Finishing the initial wait does not remove this restriction.']),
('20','When waiting periods overlap', 'If more than one waiting period applies to the same treatment, all applicable periods must be completed; the longest uncompleted period controls eligibility. Waiting does not turn a permanent exclusion into cover. For example, completing 36 months does not add maternity cover to this base policy.', ['All applicable waiting periods must be satisfied.','A permanent exclusion remains excluded after waiting periods finish.']),
]),
('Premiums, lapse and renewal', [
('21','Payment choice and annual commitment', 'The selected payment frequency is annual: INR 12,000 is due at the beginning of the policy year. A monthly instalment option of INR 1,000 exists only if separately selected in the schedule; it is not selected here. Annual payment does not buy permanent or lifetime cover. Another premium is required for a renewed policy year.', ['This schedule requires INR 12,000 annually; the INR 1,000 monthly option is not selected.','Annual payment buys one policy year, not lifetime cover.']),
('22','Renewal grace period', 'The renewal premium has a 15-day grace period after the current policy ends. No claims arising in the gap are covered until payment is received. If payment is received within the grace period, accumulated waiting-period credit is preserved, but gap claims remain excluded. Grace is not free cover.', ['Renewal grace lasts 15 days.','Claims arising in the unpaid gap are excluded, even if payment is later made within grace.','Payment within grace preserves waiting-period credit.']),
('23','Lapse after grace', 'If renewal payment is not received by the end of the 15-day grace period, the policy lapses. A later application is treated as a new policy and waiting periods restart. A claim for treatment that qualified during the prior active period may still be submitted within the claim deadline; lapse alone does not erase that prior-period claim.', ['Failure to pay by the end of grace causes lapse.','A later new policy restarts waiting periods.','An otherwise eligible prior-period claim can still be submitted on time.']),
('24','Renewal price changes', 'The insurer may propose a different premium for the next policy year and must send the proposed renewal terms at least 30 days before expiry under this invented contract. The current-year premium and benefits are not changed retrospectively by that proposal. Renewal is not a promise that the price will remain INR 12,000 forever.', ['Next-year premiums may change with at least 30 days notice.','The proposal does not retrospectively change current-year terms.','The current premium is not fixed forever.']),
]),
('Claims and customer responsibilities', [
('25','Planned hospital admission', 'For a planned admission, request cashless authorisation at least 48 hours before admission when practicable. Authorisation is a preliminary assessment, not a guarantee that every billed item will be paid. Final payment uses the actual eligible expenses and policy limits. A cashless refusal does not itself prevent an eligible reimbursement claim.', ['Request planned cashless authorisation at least 48 hours in advance when practicable.','Authorisation does not guarantee payment of the entire bill.','Cashless refusal does not automatically rule out reimbursement.']),
('26','Emergency notification', 'For an emergency admission, notify the insurer within 48 hours after admission when reasonably possible. If the member is unconscious or communications are unavailable, notification may be made within 7 days after the obstacle ends, with an explanation. The stated obstacle exception is part of this policy and must not be omitted when explaining the deadline.', ['Emergency notification is normally due within 48 hours.','Unconsciousness or unavailable communications allows notification within 7 days after the obstacle ends, with an explanation.']),
('27','Reimbursement and supporting records', 'Submit a reimbursement claim within 30 days after discharge, including an itemised bill, discharge summary and proof of payment. Treatment in a non-network hospital can qualify under the same coverage conditions. If documents are incomplete, the insurer requests the missing records; missing records alone do not establish that treatment is excluded. The claim remains pending until sufficient evidence is supplied.', ['Reimbursement is submitted within 30 days after discharge with the listed records.','Non-network treatment can qualify.','Incomplete records cause a request for evidence and a pending claim, not automatic proof of excluded treatment.']),
('28','Worked claim calculation', 'Assume INR 60,000 of otherwise eligible expenses after benefit sublimits, no prior eligible expense in that policy year, and sufficient annual limit. The deductible is INR 10,000, leaving INR 50,000. The member co-payment is INR 5,000 and the insurer pays INR 45,000. The member pays INR 15,000 plus any excluded expenses. A later claim in that year does not incur a fresh INR 10,000 deductible once it is exhausted.', ['In the stated example the insurer pays INR 45,000 and the member pays INR 15,000 plus exclusions.','The annual aggregate deductible is not charged again after it is exhausted.']),
]),
('Cancellation, changes and review', [
('29','Initial cancellation window', 'The member may request cancellation within 15 days after receiving the policy document. If no claim has been paid, the refund is the paid premium less a fixed INR 100 processing charge. If any claim has already been paid, there is no refund under this initial-window clause. The window starts on document receipt, not on the payment date.', ['The initial cancellation window is 15 days from receipt of the policy document.','With no paid claim the refund deducts INR 100.','A paid claim removes the refund under this clause.','Receipt date, not payment date, starts the window.']),
('30','Cancellation after the initial window', 'After the initial 15-day window, the member may cancel by written request. If no claim has been paid in that policy year, the insurer refunds the premium for whole unused months only, less INR 100. A started month counts as used. If any claim has been paid during that year, no premium refund is due. Cover ends on the effective cancellation date.', ['After the initial window, written cancellation is allowed.','With no paid claim, only whole unused months are refunded, less INR 100.','A started month is used and any paid claim removes that year refund.','Cover ends on the effective cancellation date.']),
('31','Changes, optional riders and spoken promises', 'Only the schedule and a written endorsement accepted for this policy change the selected options. A salesperson mentioning a rider does not add it. There is no maternity, outpatient or air-ambulance rider in the present schedule. Any proposed change must specify its price and effective date before it becomes part of this fictional agreement.', ['A written schedule or accepted endorsement is needed to change options.','Mentioning a rider does not include it.','This schedule has no maternity, outpatient or air-ambulance rider.','A proposed change must specify price and effective date.']),
('32','Claim explanation, review and meaning of this document', 'For a declined or reduced claim, the fictional insurer provides the reason and the relevant clause in writing. The member may request internal review within 30 days after receiving that explanation. Internal review does not guarantee a changed outcome. This entire policy is synthetic test material: no real insurance is sold, no real premium is payable and no real claims service exists.', ['A reduced or declined claim receives a written reason and clause reference.','Internal review may be requested within 30 days of receiving the explanation.','Review does not guarantee reversal.','This is synthetic material with no actual cover or payable premium.']),
])]

ink=colors.HexColor('#172D30'); teal=colors.HexColor('#11766E'); muted=colors.HexColor('#587071'); pale=colors.HexColor('#EDF2EC')
styles={
 'kicker':ParagraphStyle('kicker',fontName='Helvetica-Bold',fontSize=9,leading=12,textColor=teal,spaceAfter=10),
 'title':ParagraphStyle('title',fontName='Helvetica-Bold',fontSize=28,leading=32,textColor=ink,spaceAfter=14),
 'section':ParagraphStyle('section',fontName='Helvetica-Bold',fontSize=21,leading=25,textColor=ink,spaceAfter=15),
 'clause':ParagraphStyle('clause',fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=ink,spaceBefore=9,spaceAfter=5),
 'body':ParagraphStyle('body',fontName='Helvetica',fontSize=10,leading=14.3,textColor=ink,spaceAfter=8),
 'small':ParagraphStyle('small',fontName='Helvetica',fontSize=8.5,leading=12,textColor=muted,spaceAfter=7),
}
def para(text,style='body'):
 return Paragraph(escape(text),styles[style])

def chrome(canvas,doc):
 w,h=A4
 canvas.setFillColor(teal);canvas.rect(0,h-9,w,9,fill=1,stroke=0)
 canvas.setFont('Helvetica-Bold',8);canvas.setFillColor(teal)
 canvas.drawString(44,h-31,'NIVARA / CLEARCARE')
 canvas.setFont('Helvetica',8);canvas.setFillColor(muted)
 canvas.drawRightString(w-44,h-31,'DEMO-1.0 | FICTIONAL POLICY')
 canvas.setStrokeColor(pale);canvas.line(44,41,w-44,41)
 canvas.setFont('Helvetica',7.5)
 canvas.drawString(44,28,'SYNTHETIC TEST DATA - No real cover, premium or insurance advice.')
 canvas.drawRightString(w-44,28,f'{doc.page} / 8')

story=[]; inventory=[]
for page,(heading,clauses) in enumerate(SECTIONS,1):
 if page==1:
  story += [para('HMH EXTRACTION TEST / FULL FICTIONAL POLICY','kicker'),para('Nivara ClearCare','title'),para('Individual hospital-expense insurance\nComplete fictional wording and selected schedule','section')]
  notice=Table([[para('All names, dates, prices, cover rules and deadlines in this document are invented for software testing. This is not issued by a real insurer and does not describe any applicable insurance law.','small')]],colWidths=[A4[0]-108])
  notice.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('BOX',(0,0),(-1,-1),0.5,pale),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
  story += [notice,Spacer(1,12)]
 else:
  story += [para(f'{page:02d} / POLICY WORDING','kicker'),para(heading,'section')]
 for number,title,text,facts in clauses:
  story += [KeepTogether([para(f'Clause {number} | {title}','clause'),para(text)])]
  inventory.append({'clause_id':number,'page':page,'title':title,'source_text':text,'expected_facts':facts})
 if page==1:
  story += [Spacer(1,9),para('How to read this policy','clause'),para('The schedule selects the member, dates, benefit limit and payment option. The remaining pages define the benefits, cost sharing, exceptions and procedures. Read applicable clauses together: an exception to one restriction does not automatically remove another restriction.'),para('Contents','clause')]
  for n,(name,_) in enumerate(SECTIONS[1:],2): story.append(para(f'Page {n}: {name}','small'))
  story.append(para('All 32 numbered clauses form this fictional policy. There are no external terms or hidden endorsements. The separate reviewer checklist is a testing aid, not part of the policy.','small'))
 if page<8: story.append(PageBreak())

pdf=OUT/'nivara_clearcare_fictional_policy.pdf'
SimpleDocTemplate(str(pdf),pagesize=A4,rightMargin=44,leftMargin=44,topMargin=58,bottomMargin=57,title='Nivara ClearCare - Complete Fictional Insurance Policy',author='HMH synthetic test fixture').build(story,onFirstPage=chrome,onLaterPages=chrome)
(OUT/'nivara_clearcare_clause_inventory.json').write_text(json.dumps({'synthetic':True,'policy_version':'DEMO-1.0','expected_clause_count':32,'note':'Human-authored test checklist, not model-produced labels or a guarantee that one topic must equal one clause. Do not upload this inventory with the policy.','clauses':inventory},indent=2)+'\n')
lines=['HMH REVIEWER CHECKLIST - DO NOT UPLOAD THIS FILE WITH THE POLICY','Nivara ClearCare DEMO-1.0 | All terms invented | 32 numbered clauses across 8 pages','', 'Evaluate coverage by facts, not by matching the topic count: the extractor may reasonably group or split topics.','Check source-page accuracy, numeric values, exception handling, omissions and invented facts.','']
for c in inventory:
 lines += [f"Clause {c['clause_id']} | Page {c['page']} | {c['title']}"] + ['  [ ] '+fact for fact in c['expected_facts']] + ['']
lines += ['HIGH-VALUE TRAPS TO CHECK','- Annual INR 12,000 is selected. The INR 1,000 monthly option is NOT selected.','- Family members are not included.','- INR 10,000 deductible is annual aggregate, not per admission.','- Room excess does not proportionately reduce other eligible treatment charges.','- Day-care and accidental dental exceptions must not disappear.','- Overseas emergencies are excluded.','- High-altitude climbing exclusion is not a blanket high-altitude travel exclusion.','- The emergency notification deadline has an obstacle exception.','- Unpaid grace-period gap claims stay excluded.','- Completing waiting periods never adds a permanently excluded benefit.','- Cancellation refunds depend on whether a claim has been paid.','- Worked claim: INR 60,000 eligible -> INR 45,000 insurer / INR 15,000 member.','', 'No model evaluation has been performed on this fixture. Native-language generated questions need human review.']
(OUT/'nivara_clearcare_reviewer_checklist.txt').write_text('\n'.join(lines)+'\n')
print(pdf)
print(f'Wrote {len(inventory)} clauses and independent expected-fact inventory.')
